package com.mediexplain.service;
import com.mediexplain.model.*;import com.mediexplain.repo.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ConversationService {
 private final ConversationRepository conversations;private final MessageRepository messages;private final ReportRepository reports;private final GeminiService gemini;
 public ConversationService(ConversationRepository c,MessageRepository m,ReportRepository r,GeminiService g){conversations=c;messages=m;reports=r;gemini=g;}
 @Transactional public Conversation start(AppUser owner,Long reportId){MedicalReport report=reports.findByIdAndOwner(reportId,owner).orElseThrow(()->new NoSuchElementException("Report not found."));return conversations.save(new Conversation(owner,report,"Questions about "+report.getFilename()));}
 @Transactional public Message ask(AppUser owner,Long id,String question,String submissionKey){String q=question==null?"":question.trim();if(q.isBlank()||q.length()>1000)throw new IllegalArgumentException("Enter a question of 1 to 1,000 characters.");if(submissionKey==null||!submissionKey.matches("[0-9a-fA-F-]{36}"))throw new IllegalArgumentException("Please resubmit your question.");Conversation c=conversations.findByIdAndOwner(id,owner).orElseThrow(()->new NoSuchElementException("Conversation not found."));var duplicate=messages.findByConversationAndSubmissionKey(c,submissionKey);if(duplicate.isPresent())return duplicate.get();List<Message> old=messages.findByConversationOrderByCreatedAtAsc(c);List<String> recent=old.stream().skip(Math.max(0,old.size()-6)).map(m->"User: "+m.getQuestion()+"\nAssistant: "+m.getAnswer()).toList();String answer=gemini.explain(c.getReport().getExtractedText(),q,recent);return messages.save(new Message(c,q,answer,submissionKey));}
}
